      "answer": 50,
      "unit": "%",
      "tolerance": 1.1,
      "solution": [
        "A user stays put only if `hash % 8` equals `hash % 4`.",
        "`hash % 8` is either `hash % 4` or `hash % 4 + 4`, each for half of all hashes.",
        "So half the users stay, and the other half move, each to one of the four new shards."
      ]
