    "question": {
      "kind": "numeric",
      "prompt": "The description is 20 characters long. Maya inserts 6 characters at position 16, and at the same moment Sam inserts text at position 20. Under operational transformation, at what position does Sam’s insert land on Maya’s copy?",
      "answer": 26,
      "unit": "position",
      "tolerance": 1.03,
      "solution": [
        "Maya’s insert comes before position 20, so it pushes everything after it to the right.",
        "She added 6 characters, so Sam’s position moves by 6.",
        "20 + 6 = 26."
      ]
    }
